package dev.equalparts.glyph_catch.screens.garden

// Generated by glyphcatch-work/emerald/town.js from the same layout as garden_scene_town.png

/** A place on the town map, in tiles: its area and the tile in front of its door. */
internal class TownArea(val x: Int, val y: Int, val width: Int, val height: Int, val doorX: Int, val doorY: Int) {
    fun contains(tileX: Int, tileY: Int) = tileX in x until x + width && tileY in y until y + height
}

internal object TownMapData {
    const val TILE = 16
    const val WIDTH = 20
    const val HEIGHT = 33

    /** '#' can't be walked on: trees, buildings, fences, water, rocks and flowers. '=' is path, '.' grass. */
    val SOLID = listOf(
        "####################",
        "####################",
        "########...######.##",
        "########...######.##",
        "########...######.##",
        "########...######.##",
        "########...######.##",
        "##...........===..##",
        "##..============..##",
        "##..============..##",
        "##..#....==.......##",
        "##.....#.==.......##",
        "##...#..#==.......##",
        "##.......==.#####.##",
        "##.#.....==.#####.##",
        "##.....#.==.#####.##",
        "###......==.#####.##",
        "##..#....==..===..##",
        "##......#==..===....",
        "##.#..#..==..===....",
        "##..#..#.===========",
        "##.......===========",
        "#########==.........",
        "#########==...##..##",
        "#########==...##..##",
        "#########==.########",
        "#########==.##..####",
        "#########==.##..####",
        "##..=======.......##",
        "##..=======.......##",
        "##................##",
        "####################",
        "####################"
    )

    val PLACES = mapOf(
        "springs" to TownArea(2, 2, 6, 6, 5, 8),
        "gym" to TownArea(11, 2, 6, 5, 14, 7),
        "kitchen" to TownArea(12, 13, 5, 4, 14, 17),
        "meadow" to TownArea(2, 12, 7, 9, 6, 16),
        "orchard" to TownArea(2, 22, 7, 6, 5, 28)
    )

    fun walkable(x: Int, y: Int) = x in 0 until WIDTH && y in 0 until HEIGHT && SOLID[y][x] != '#'

    fun isPath(x: Int, y: Int) = x in 0 until WIDTH && y in 0 until HEIGHT && SOLID[y][x] == '='
}
